// Wraps operand text in brackets unless it is a plain unsigned number or
// already one closed group, so the tape reads √9 and 1/(2 + 3).
function bracket(text) {
  if (/^\d+(\.\d+)?(e[+-]\d+)?$/.test(text)) return text;
  if (text.charAt(0) === '(') {
    var depth = 0;
    for (var i = 0; i < text.length; i++) {
      depth += text.charAt(i) === '(' ? 1 : text.charAt(i) === ')' ? -1 : 0;
      if (depth === 0) break;
    }
    if (i === text.length - 1) return text;
  }
  return '(' + text + ')';
}

var UNARY = {
  sqrt: { fn: Math.sqrt, text: function (t) { return '√' + bracket(t); } },
  square: { fn: function (x) { return x * x; }, text: function (t) { return bracket(t) + '²'; } },
  recip: { fn: function (x) { return 1 / x; }, text: function (t) { return '1/' + bracket(t); } }
};

// √x, x² and 1/x act at once on the number shown, even when an operator is
// waiting (9 + √ gives 9 + 3). The result is a finished entry, like a closed
// group. A non-finite result (√ of a negative, 1/0, overflow) is an error.
